// ===== 状态变量 (0-based) =====
    let currentChapterId = 'ch1';
    let current = 0;
    let showSolution = true;
    let defaultShowSolution = true;
    let statuses = {};
    let qBad = {};   // R键：题目图不达标  { idx: true }
    let sBad = {};   // T键：解析图不达标  { idx: true }
    let currentFilters = new Set(['all']);
    let subMode = false; // F键：小题选择模式（仅当前题组含子题时生效）
    let visualRows = []; // W/S 视觉行映射，每个元素是一个数组包含该行的 group.startIdx

    function isAllFilterActive() {
      return currentFilters.has('all') || currentFilters.size === 0;
    }

    function getChapter() { return CHAPTERS.find(c => c.id === currentChapterId); }

    // ===== 题组（父题/子题）解析 =====
    // 去掉 label 末尾括号及内容（支持 (1)、(a)、(I)、全角括号），得到父题号
    function stripSubSuffix(label) { return String(label).replace(/\s*[\(（][^\)）]*[\)）]\s*$/, ''); }
    // 提取 label 末尾括号内容，如 '3-4(1)' -> '(1)'；无括号返回原 label
    function subSuffix(label) { const m = String(label).match(/[\(（][^\)）]*[\)）]\s*$/); return m ? m[0].trim() : String(label); }

    // 为章节计算 subGroups / groupForIdx（懒计算，缓存在章节对象上）
    function ensureGroups(ch) {
      if (ch.subGroups && ch.groupForIdx) return;
      const labels = ch.labels || [];
      const groups = [];
      let i = 0;
      while (i < labels.length) {
        const parent = stripSubSuffix(labels[i]);
        const hasParen = parent !== labels[i];
        let j = i + 1;
        if (hasParen) {
          while (j < labels.length && stripSubSuffix(labels[j]) === parent && stripSubSuffix(labels[j]) !== labels[j]) j++;
        }
        groups.push({ parentLabel: parent, startIdx: i, count: j - i, isParent: hasParen && (j - i) > 1 });
        i = j;
      }
      ch.subGroups = groups;
      ch.groupForIdx = new Array(labels.length);
      groups.forEach(g => { for (let k = 0; k < g.count; k++) ch.groupForIdx[g.startIdx + k] = g; });
    }

    // 题组内当前筛选下可见的索引列表
    function groupVisibleIndices(g) {
      const set = new Set(getFilteredIndices());
      const out = [];
      for (let k = 0; k < g.count; k++) { const idx = g.startIdx + k; if (set.has(idx)) out.push(idx); }
      return out;
    }
    function storageKey() { return currentChapterId + '_s1_status'; }
    function qBadStorageKey() { return currentChapterId + '_s1_qbad'; }
    function sBadStorageKey() { return currentChapterId + '_s1_sbad'; }
    function totalQuestions() { return getChapter().total; }

    // ===== 筛选相关 =====
    function updateFilterButtons() {
      document.querySelectorAll('.filter-btn').forEach(b => {
        const active = currentFilters.has(b.dataset.filter);
        b.classList.toggle('active', active);
        b.setAttribute('aria-pressed', active ? 'true' : 'false');
      });
    }

    function applyFilter(filterKey) {
      if (filterKey === 'all') {
        currentFilters = new Set(['all']);
      } else {
        if (currentFilters.has('all')) currentFilters.delete('all');
        if (currentFilters.has(filterKey)) {
          currentFilters.delete(filterKey);
          if (currentFilters.size === 0) currentFilters.add('all');
        } else {
          currentFilters.add(filterKey);
        }
      }
      updateFilterButtons();
      const filtered = getFilteredIndices();
      updateFilterCounts();
      if (filtered.length > 0 && !isFiltered(current)) {
        switchTo(filtered[0]);
      } else {
        renderNav();
      }
    }

    function getFilteredIndices() {
      const ch = getChapter();
      const all = Array.from({ length: ch.total }, (_, i) => i);
      if (isAllFilterActive()) return all;
      return all.filter(i => {
        if (!statuses[i]) return currentFilters.has('unmarked');
        return currentFilters.has(statuses[i]);
      });
    }
    function filteredTotal() { return getFilteredIndices().length; }
    function filteredIndex(idx) { return getFilteredIndices().indexOf(idx); }
    function isFiltered(idx) { return filteredIndex(idx) !== -1; }

    // ===== localStorage 持久化 =====
    function loadStatuses() {
      try {
        let raw = JSON.parse(localStorage.getItem(storageKey())) || {};
        statuses = migrateChapterData(raw, currentChapterId);
        saveStatuses();
      } catch (e) { statuses = {}; }
    }
    function saveStatuses() { localStorage.setItem(storageKey(), JSON.stringify(statuses)); pushCloudChapterData(currentChapterId, 'status', statuses); }
    function loadQBad() {
      try {
        let raw = JSON.parse(localStorage.getItem(qBadStorageKey())) || {};
        qBad = migrateChapterData(raw, currentChapterId);
        saveQBad();
      } catch (e) { qBad = {}; }
    }
    function saveQBad() { localStorage.setItem(qBadStorageKey(), JSON.stringify(qBad)); pushCloudChapterData(currentChapterId, 'qbad', qBad); }
    function loadSBad() {
      try {
        let raw = JSON.parse(localStorage.getItem(sBadStorageKey())) || {};
        sBad = migrateChapterData(raw, currentChapterId);
        saveSBad();
      } catch (e) { sBad = {}; }
    }
    function saveSBad() { localStorage.setItem(sBadStorageKey(), JSON.stringify(sBad)); pushCloudChapterData(currentChapterId, 'sbad', sBad); }

    // ===== 笔记数据 =====
    let notesData = {};
    function notesStorageKey() { return currentChapterId + '_s1_notes'; }
    function loadNotes() {
      try { notesData = JSON.parse(localStorage.getItem(notesStorageKey())) || {}; } catch (e) { notesData = {}; }
    }
    function saveNotes() { localStorage.setItem(notesStorageKey(), JSON.stringify(notesData)); pushCloudChapterData(currentChapterId, 'notes', notesData); }

    function getStatusClass(idx) {
      const s = statuses[idx];
      if (s === 'proficient') return 'proficient';
      if (s === 'vague') return 'vague';
      if (s === 'wrong') return 'wrong';
      return '';
    }

    // ===== 图片路径 =====
        function getImgPath(idx) {
      const ch = getChapter();
      if (ch.category === 'zhuanye' && ch.fileBases && ch.fileBases[idx]) {
        return '专业题库/' + ch.relPath + '/' + ch.fileBases[idx];
      }
      const label = ch.labels[idx];
      const relPath = ch.relPath;
      let prefix, numPart;
      if (label.startsWith('例')) {
        prefix = 'ex';
        numPart = label.substring(1);
      } else {
        prefix = 'pb';
        numPart = label;
      }
      return '数一题库/' + relPath + '/' + prefix + '_' + numPart;
    }


    // ===== 章节切换 =====
    function switchChapter(chapterId) {
      const ch = CHAPTERS.find(c => c.id === chapterId);
      if (!ch || ch.total === 0) { alert('该章节尚未导入'); return; }
      currentChapterId = chapterId;
      current = 0;
      showSolution = defaultShowSolution;
      subMode = false;
      applyFilter('all');
      loadStatuses(); loadQBad(); loadSBad(); loadNotes();
      renderTitle();
      renderStats();
      renderNav(); switchTo(0);
    }

    function gotoPrevChapter() {
      let idx = CHAPTERS.findIndex(c => c.id === currentChapterId);
      for (let i = idx - 1; i >= 0; i--) { if ((CHAPTERS[i].category || 'shu1') === currentCategory && CHAPTERS[i].total > 0) { switchChapter(CHAPTERS[i].id); return; } }
    }
    function gotoNextChapter() {
      let idx = CHAPTERS.findIndex(c => c.id === currentChapterId);
      for (let i = idx + 1; i < CHAPTERS.length; i++) { if ((CHAPTERS[i].category || 'shu1') === currentCategory && CHAPTERS[i].total > 0) { switchChapter(CHAPTERS[i].id); return; } }
    }

